Definition gfa_frame (m : mem) (sp : word) (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) : Prop :=
  exists junk, rw_cells asegs m (bv_unsigned sp - 128)
