Fixpoint dest (ws chs : list word) (base : Z) (i : nat) : list word :=
  match i with
  | O => chs
  | S j => upd (dest ws chs base j) j (sx32 (nth (Z.to_nat base + j) ws (Z_to_bv 64 0)))
  end.

