  SB_ok ACEIL SB -> (1 <= c <= 31)%Z -> R = rinfo (RIS_of SB) c ->
  (1 <= n <= 16)%Z -> (n <= nfree)%Z -> (4 * nfree <= 4 * Z.of_nat (length ws) <= 2^29)%Z -> length chs = 16%nat ->
  (0 < CH /\ CH + 64 <= ACEIL /\ (CH + 64 <= SB \/ SB + 2^37 + 4096 <= CH))%Z ->
